import { Link } from 'react-router-dom';
import { useTheme } from '../contexts/ThemeContext';

const links = [
  { label: 'Home', to: '/' },
  { label: 'Dashboard', to: '/dashboard' },
  { label: 'Fundamentals', to: '/fundamentals' },
  { label: 'Roadmap', to: '/roadmap' },
];

export default function Navbar() {
  const { isDark, toggleTheme } = useTheme();

  return (
    <header className="sticky top-0 z-40 border-b border-slate-200 bg-gradient-to-r from-white/80 via-blue-50/80 to-teal-50/80 backdrop-blur-xl dark:border-slate-700 dark:bg-gradient-to-r dark:from-slate-800/80 dark:via-slate-800/80 dark:to-slate-800/80">
      <div className="mx-auto flex max-w-7xl items-center justify-between px-5 py-4">
        <Link to="/" className="text-lg font-semibold tracking-wide text-teal-600 dark:text-teal-300">
          LearnAI Studio
        </Link>
        <div className="flex items-center gap-4">
          <button
            onClick={toggleTheme}
            className="rounded-full p-2 text-cyan-300 hover:bg-indigo-800/50 hover:text-white dark:text-cyan-600 dark:hover:bg-blue-300/50 dark:hover:text-slate-900"
          >
            {isDark ? '☀️' : '🌙'}
          </button>
          <nav className="hidden items-center gap-4 lg:flex">
            {links.map((link) => (
              <Link
                key={link.to}
                to={link.to}
                className="rounded-xl px-4 py-2 text-sm font-medium text-cyan-200 transition hover:bg-indigo-800/50 hover:text-white dark:text-cyan-700 dark:hover:bg-blue-300/50 dark:hover:text-slate-900"
              >
                {link.label}
              </Link>
            ))}
          </nav>
        </div>
      </div>
    </header>
  );
}
